DEFINER = 'root'@'localhost'
PROCEDURE sp_areas_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    a.id_area,
    a.nombre,
    ta.nombre AS tipo_area
  FROM areas a
    JOIN tipos_area ta
      ON a.id_tipo_area = ta.id_tipo_area
  WHERE a.nombre LIKE CONCAT('%', p_term, '%')
  OR ta.nombre LIKE CONCAT('%', p_term, '%')
  ORDER BY a.nombre;
END
$$

