    sa.id_sub_area,
    sa.descripcion,
    sa.numero_sub_area,
    sa.capacidad_maxima,
    a.nombre AS area_nombre
  FROM sub_areas sa
    JOIN areas a
      ON sa.id_area = a.id_area
  ORDER BY a.nombre, sa.descripcion;
END
