-- Create index `nombre_usuario_UNIQUE` on table `usuarios`
--
ALTER TABLE usuarios
ADD UNIQUE INDEX nombre_usuario_UNIQUE (nombre_usuario);

--
-- Create index `email_UNIQUE` on table `usuarios`
--
ALTER TABLE usuarios
ADD UNIQUE INDEX email_UNIQUE (email);

--
-- Create index `fk_usuarios_roles_idx` on table `usuarios`
--
ALTER TABLE usuarios
ADD INDEX fk_usuarios_roles_idx (id_rol);

--
-- Create foreign key
--
ALTER TABLE usuarios
ADD CONSTRAINT fk_usuarios_roles FOREIGN KEY (id_rol)
REFERENCES roles (id_rol) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_usuarios_verificar_codigo_2fa`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_verificar_codigo_2fa (IN p_id_usuario int,
IN p_codigo varchar(10))
BEGIN
  SELECT
    id_usuario
  FROM usuarios
  WHERE id_usuario = p_id_usuario
  AND auth_2fa_code = p_codigo
  AND auth_2fa_expiry > NOW();
END
$$

--
-- Create procedure `sp_usuarios_obtener_por_nombre`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_obtener_por_nombre (IN p_nombre_usuario varchar(50))
BEGIN
  SELECT
    id_usuario,
    id_rol,
    nombre_usuario,
    password_hash,
    email,
    nombre_completo,
    activo
  FROM usuarios
  WHERE nombre_usuario = p_nombre_usuario
  AND activo = 1;
END
$$

--
-- Create procedure `sp_usuarios_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_obtener_por_id (IN p_id_usuario int)
BEGIN
  SELECT
    u.id_usuario,
    u.id_rol,
    r.nombre_rol,
    u.nombre_usuario,
    u.email,
    u.nombre_completo,
    u.activo,
    u.fecha_creacion
  FROM usuarios u
    JOIN roles r
      ON u.id_rol = r.id_rol
  WHERE u.id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_listar ()
BEGIN
  SELECT
    u.id_usuario,
    u.id_rol,
    r.nombre_rol,
    u.nombre_usuario,
    u.email,
    u.nombre_completo,
    u.activo
  FROM usuarios u
    JOIN roles r
      ON u.id_rol = r.id_rol
  ORDER BY u.nombre_completo;
END
$$

--
-- Create procedure `sp_usuarios_guardar_codigo_2fa`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_guardar_codigo_2fa (IN p_id_usuario int,
IN p_codigo varchar(10),
IN p_expiracion datetime)
BEGIN
  UPDATE usuarios
  SET auth_2fa_code = p_codigo,
      auth_2fa_expiry = p_expiracion
  WHERE id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_eliminar (IN p_id_usuario int)
BEGIN
  UPDATE usuarios
  SET activo = 0
  WHERE id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_crear (IN p_id_rol int,
IN p_nombre_usuario varchar(50),
IN p_password_hash varchar(255),
IN p_email varchar(100),
IN p_nombre_completo varchar(150))
BEGIN
    VALUES (p_id_rol, p_nombre_usuario, p_password_hash, p_email, p_nombre_completo, 1);
END
$$

--
-- Create procedure `sp_usuarios_cambiar_password`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_cambiar_password (IN p_id_usuario int,
IN p_password_hash varchar(255))
BEGIN
  UPDATE usuarios
  SET password_hash = p_password_hash
  WHERE id_usuario = p_id_usuario;
END
$$

--
-- Create procedure `sp_usuarios_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_usuarios_actualizar (IN p_id_usuario int,
IN p_id_rol int,
IN p_nombre_usuario varchar(50),
IN p_email varchar(100),
IN p_nombre_completo varchar(150),
IN p_activo tinyint(1))
BEGIN
  UPDATE usuarios
  SET id_rol = p_id_rol,
      nombre_usuario = p_nombre_usuario,
      email = p_email,
      nombre_completo = p_nombre_completo,
      activo = p_activo
  WHERE id_usuario = p_id_usuario;
END
$$

