--
-- Create procedure `sp_tipos_documento_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_eliminar (IN p_id int)
BEGIN
  DELETE
    FROM tipos_documento
  WHERE id_tipo_documento = p_id;
END
$$

--
-- Create procedure `sp_tipos_documento_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_crear (IN p_descripcion varchar(50),
IN p_longitud int,
IN p_codigo_sunat varchar(2))
BEGIN
    VALUES (p_descripcion, p_longitud, p_codigo_sunat);
