--
-- Create table `profesores`
--
CREATE TABLE profesores (
  id_profesor int(11) NOT NULL AUTO_INCREMENT,
  id_tipo_documento int(11) NOT NULL,
  numero_documento varchar(20) NOT NULL,
  nombres varchar(100) NOT NULL,
  apellidos varchar(100) NOT NULL,
  email varchar(100) DEFAULT NULL,
  telefono varchar(20) DEFAULT NULL,
  especialidad varchar(255) DEFAULT NULL,
  PRIMARY KEY (id_profesor)
)
ENGINE = INNODB,
AUTO_INCREMENT = 5,
AVG_ROW_LENGTH = 4096,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `documento_UNIQUE` on table `profesores`
--
ALTER TABLE profesores
ADD UNIQUE INDEX documento_UNIQUE (id_tipo_documento, numero_documento);

--
-- Create index `fk_profesores_tipos_documento_idx` on table `profesores`
--
ALTER TABLE profesores
ADD INDEX fk_profesores_tipos_documento_idx (id_tipo_documento);

--
-- Create foreign key
--
ALTER TABLE profesores
ADD CONSTRAINT fk_profesores_tipos_documento FOREIGN KEY (id_tipo_documento)
REFERENCES tipos_documento (id_tipo_documento) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_profesores_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_obtener_por_id (IN p_id int)
BEGIN
  SELECT
    id_profesor,
    id_tipo_documento,
    numero_documento,
    nombres,
    apellidos,
    email,
    telefono,
    especialidad
  FROM profesores
  WHERE id_profesor = p_id;
END
$$

--
-- Create procedure `sp_profesores_listar_simple`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_listar_simple ()
BEGIN
  SELECT
    id_profesor,
    CONCAT(apellidos, ', ', nombres) AS nombre_completo
  FROM profesores
  ORDER BY apellidos;
END
$$

--
-- Create procedure `sp_profesores_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_listar ()
BEGIN
  SELECT
    p.id_profesor,
    p.nombres,
    p.apellidos,
    p.email,
    p.telefono,
    p.especialidad,
    td.descripcion AS tipo_documento,
    p.numero_documento
  FROM profesores p
    JOIN tipos_documento td
      ON p.id_tipo_documento = td.id_tipo_documento
  ORDER BY p.apellidos, p.nombres;
END
$$

--
-- Create procedure `sp_profesores_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_eliminar (IN p_id int)
BEGIN
  -- Se podría añadir lógica para verificar dependencias antes de eliminar
  DELETE
    FROM profesores
  WHERE id_profesor = p_id;
END
$$

--
-- Create procedure `sp_profesores_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_crear (IN p_id_tipo_documento int,
IN p_numero_documento varchar(20),
IN p_nombres varchar(100),
IN p_apellidos varchar(100),
IN p_email varchar(100),
IN p_telefono varchar(20),
IN p_especialidad varchar(255))
BEGIN
    VALUES (p_id_tipo_documento, p_numero_documento, p_nombres, p_apellidos, p_email, p_telefono, p_especialidad);
END
$$

--
-- Create procedure `sp_profesores_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_buscar (IN p_termino varchar(100))
BEGIN
  SELECT
    id_profesor,
    CONCAT(nombres, ' ', apellidos) AS nombre_completo
  FROM profesores
  WHERE CONCAT(nombres, ' ', apellidos) LIKE CONCAT('%', p_termino, '%')
  ORDER BY apellidos, nombres
  LIMIT 10;
END
$$

--
-- Create procedure `sp_profesores_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_profesores_actualizar (IN p_id_profesor int,
IN p_id_tipo_documento int,
IN p_numero_documento varchar(20),
IN p_nombres varchar(100),
IN p_apellidos varchar(100),
IN p_email varchar(100),
IN p_telefono varchar(20),
IN p_especialidad varchar(255))
BEGIN
  UPDATE profesores
  SET id_tipo_documento = p_id_tipo_documento,
      numero_documento = p_numero_documento,
      nombres = p_nombres,
      apellidos = p_apellidos,
      email = p_email,
      telefono = p_telefono,
      especialidad = p_especialidad
  WHERE id_profesor = p_id_profesor;
END
$$

DELIMITER ;

