  direccion varchar(255) DEFAULT NULL,
  codigo_ubigeo varchar(10) DEFAULT NULL,
  observaciones text DEFAULT NULL,
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP(),
  PRIMARY KEY (id_cliente)
)
ENGINE = INNODB,
