REFERENCES tipos_documento (id_tipo_documento) ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_tipos_documento_verificar_dependencias`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_documento_verificar_dependencias (IN p_id_tipo_documento int)
BEGIN
  SELECT
    COUNT(id_cliente) AS count
  FROM clientes
  WHERE id_tipo_documento = p_id_tipo_documento;
END
$$

--
-- Create procedure `sp_clientes_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_clientes_obtener_por_id (IN p_id_cliente int)
BEGIN
