--
ALTER TABLE cobros
ADD CONSTRAINT fk_cobros_matricula FOREIGN KEY (id_matricula)
REFERENCES matriculas (id_matricula) ON DELETE CASCADE ON UPDATE CASCADE;

DELIMITER $$

--
-- Create procedure `sp_cobros_saldo_matricula`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cobros_saldo_matricula (IN p_id_matricula int,
IN p_id_cobro_excluir int)
BEGIN
  SELECT
    m.monto_final - COALESCE(SUM(CASE WHEN c.id_cobro = p_id_cobro_excluir THEN 0 ELSE c.importe END), 0) AS saldo_pendiente
  FROM matriculas m
    LEFT JOIN cobros c
      ON c.id_matricula = m.id_matricula
  WHERE m.id_matricula = p_id_matricula
  GROUP BY m.id_matricula,
           m.monto_final;
END
$$

--
-- Create procedure `sp_cobros_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cobros_eliminar (IN p_id_cobro int)
BEGIN
  DELETE
    FROM cobros
  WHERE id_cobro = p_id_cobro;
END
$$

--
-- Create procedure `sp_cobros_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cobros_crear (IN p_id_matricula int,
IN p_id_forma_pago int,
IN p_fecha_cobro date,
IN p_numero_operacion varchar(20),
IN p_importe decimal(10, 2),
IN p_observaciones text,
IN p_id_usuario_creacion int)
BEGIN
  id_forma_pago,
  fecha_cobro,
  numero_operacion,
  importe,
  observaciones,
  id_usuario_creacion,
  fecha_modificacion)
    VALUES (
    p_id_matricula,
    p_id_forma_pago,
    p_fecha_cobro,
    p_numero_operacion,
    p_importe,
    p_observaciones,
    p_id_usuario_creacion,
    NULL
    );
END
$$

--
-- Create procedure `sp_cobros_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cobros_actualizar (IN p_id_cobro int,
IN p_id_forma_pago int,
IN p_fecha_cobro date,
IN p_numero_operacion varchar(20),
IN p_importe decimal(10, 2),
IN p_observaciones text)
BEGIN
  UPDATE cobros
  SET id_forma_pago = p_id_forma_pago,
      fecha_cobro = p_fecha_cobro,
      numero_operacion = p_numero_operacion,
      importe = p_importe,
      observaciones = p_observaciones,
      fecha_modificacion = NOW()
  WHERE id_cobro = p_id_cobro;
END
$$

