CREATE TABLE cursos_programados (
  id_curso_programado int(11) NOT NULL AUTO_INCREMENT,
  id_curso int(11) NOT NULL,
  id_profesor int(11) NOT NULL,
  id_sub_area int(11) NOT NULL,
  id_tipo_horario int(11) NOT NULL,
  fecha_inicio date NOT NULL,
  fecha_fin date NOT NULL,
  hora_inicio time NOT NULL,
  hora_fin time NOT NULL,
  vacantes_disponibles int(11) NOT NULL,
  estado enum ('Programado', 'En Curso', 'Finalizado', 'Cancelado') NOT NULL DEFAULT 'Programado',
  PRIMARY KEY (id_curso_programado)
)
ENGINE = INNODB,
AUTO_INCREMENT = 23,
AVG_ROW_LENGTH = 8192,
CHARACTER SET utf8mb4,
