DELIMITER $$

--
-- Create procedure `sp_matricula_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_eliminar (IN p_id_matricula int)
BEGIN
  DECLARE done int DEFAULT FALSE;
  DECLARE cur_id_curso_programado int;
  DECLARE cur_id_matricula_detalle int;

  -- Cursor para iterar sobre los detalles de la matrícula a eliminar
  DECLARE cur_detalles CURSOR FOR
  SELECT
    id_matricula_detalle,
    id_curso_programado
  FROM matriculas_detalle
  WHERE id_matricula = p_id_matricula;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

  START TRANSACTION;

    -- 1. Devolver las vacantes de cada curso en la matrícula
    OPEN cur_detalles;
  devolver_loop:
    LOOP
      FETCH cur_detalles INTO cur_id_matricula_detalle, cur_id_curso_programado;
      IF done THEN
        LEAVE devolver_loop;
      END IF;
      -- Incrementar la vacante
      UPDATE cursos_programados
      SET vacantes_disponibles = vacantes_disponibles + 1
      WHERE id_curso_programado = cur_id_curso_programado;
    END LOOP;
    CLOSE cur_detalles;

    -- 2. Eliminar los registros de asistencia asociados
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle IN (SELECT
          id_matricula_detalle
        FROM matriculas_detalle
        WHERE id_matricula = p_id_matricula);

    -- 3. Eliminar los registros de detalle
    DELETE
      FROM matriculas_detalle
    WHERE id_matricula = p_id_matricula;

    -- 4. Eliminar la cabecera
    DELETE
      FROM matriculas
    WHERE id_matricula = p_id_matricula;

  COMMIT;
END
$$

--
-- Create procedure `sp_matricula_detalle_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_detalle_eliminar (IN p_id_matricula_detalle int)
BEGIN
  DECLARE v_id_curso_programado int;

  -- Obtener el curso programado antes de eliminar
  SELECT
    id_curso_programado INTO v_id_curso_programado
  FROM matriculas_detalle
  WHERE id_matricula_detalle = p_id_matricula_detalle;

  -- Si encontramos el detalle, proceder
  IF v_id_curso_programado IS NOT NULL THEN
    -- 1. Devolver la vacante al curso
    UPDATE cursos_programados
    SET vacantes_disponibles = vacantes_disponibles + 1
    WHERE id_curso_programado = v_id_curso_programado;

    -- 2. Eliminar la asistencia generada
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle = p_id_matricula_detalle;

    -- 3. Eliminar el detalle de la matrícula
    DELETE
      FROM matriculas_detalle
    WHERE id_matricula_detalle = p_id_matricula_detalle;
  END IF;
END
$$

--
-- Create procedure `sp_matricula_anular`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_anular (IN p_id_matricula int,
IN p_observaciones text)
BEGIN
  DECLARE v_estado_actual varchar(20);

  -- Iniciar transacción
  START TRANSACTION;

    -- Verificar que la matrícula no esté ya anulada
    SELECT
      estado INTO v_estado_actual
    FROM matriculas
    WHERE id_matricula = p_id_matricula;

    IF v_estado_actual = 'Activa' THEN
      -- 1. Actualizar el estado de la matrícula y añadir la observación
      UPDATE matriculas
      SET estado = 'Anulada',
          observaciones = CONCAT(IFNULL(observaciones, ''), '\nANULACIÓN: ', p_observaciones)
      WHERE id_matricula = p_id_matricula;

      -- 2. Devolver las vacantes de los cursos asociados a esta matrícula
      UPDATE cursos_programados cp
      JOIN matriculas_detalle md
        ON cp.id_curso_programado = md.id_curso_programado
      SET cp.vacantes_disponibles = cp.vacantes_disponibles + 1
      WHERE md.id_matricula = p_id_matricula;

      -- 3. Opcional: Cambiar el estado de la asistencia del cliente a 'Cancelado'
      UPDATE asistencia_cliente ac
      JOIN matriculas_detalle md
        ON ac.id_matricula_detalle = md.id_matricula_detalle
      SET ac.estado = 'Cancelado'
      WHERE md.id_matricula = p_id_matricula;

      COMMIT;
    ELSE
      -- Si ya está anulada o completada, no hacer nada y revertir
      ROLLBACK;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La matrícula no se puede anular porque no está activa.';
    END IF;
END
$$

--
-- Create procedure `sp_asistencia_cliente_obtener_clases`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_obtener_clases (IN p_id_matricula_detalle int,
IN p_limit int,
IN p_offset int)
BEGIN
  SELECT
    id_asistencia_cliente,
    fecha_clase,
    estado,
    observaciones
  FROM asistencia_cliente
  WHERE id_matricula_detalle = p_id_matricula_detalle
  ORDER BY fecha_clase ASC
  LIMIT p_limit OFFSET p_offset;
END
$$

--
-- Create procedure `sp_asistencia_cliente_generar_cronograma`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_generar_cronograma (IN p_id_matricula_detalle int)
BEGIN
  DECLARE v_fecha_actual date;
  DECLARE v_fecha_fin date;
  DECLARE v_id_cliente int;
  DECLARE v_id_curso_programado int;
  DECLARE v_dias_semana varchar(20);

  -- Obtener datos de la programación y el cliente de asistencia
  SELECT
    cp.fecha_inicio,
    cp.fecha_fin,
    md.id_cliente_asistencia,
    cp.id_curso_programado,
    th.dias_semana INTO v_fecha_actual, v_fecha_fin, v_id_cliente, v_id_curso_programado, v_dias_semana
  FROM matriculas_detalle md
    JOIN cursos_programados cp
      ON md.id_curso_programado = cp.id_curso_programado
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE md.id_matricula_detalle = p_id_matricula_detalle;

  -- Solo generar si hay un cliente de asistencia asignado
  IF v_id_cliente IS NOT NULL THEN
    -- Limpiar cronograma existente por si se regenera
    DELETE
      FROM asistencia_cliente
    WHERE id_matricula_detalle = p_id_matricula_detalle;

    -- Bucle para generar registros de asistencia
    WHILE v_fecha_actual <= v_fecha_fin DO
      IF FIND_IN_SET(WEEKDAY(v_fecha_actual) + 1, v_dias_semana COLLATE utf8mb4_unicode_ci) THEN
          VALUES (p_id_matricula_detalle, v_id_cliente, v_fecha_actual, 'Programado');
      END IF;
      SET v_fecha_actual = DATE_ADD(v_fecha_actual, INTERVAL 1 DAY);
    END WHILE;
  END IF;
END
$$

--
-- Create procedure `sp_matricula_detalle_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_matricula_detalle_actualizar (IN p_id_matricula_detalle int,
IN p_id_cliente_asistencia int,
IN p_precio_pactado decimal(10, 2),
IN p_descuento decimal(10, 2))
BEGIN
  DECLARE v_precio_final decimal(10, 2);
  DECLARE v_cliente_actual int;

  -- Obtener el cliente de asistencia actual para comparar
  SELECT
    id_cliente_asistencia INTO v_cliente_actual
  FROM matriculas_detalle
  WHERE id_matricula_detalle = p_id_matricula_detalle;

  -- Calcular el nuevo precio final
  SET v_precio_final = p_precio_pactado - p_descuento;

  -- Actualizar el registro de detalle
  UPDATE matriculas_detalle
  SET id_cliente_asistencia = p_id_cliente_asistencia,
      precio_pactado = p_precio_pactado,
      descuento = p_descuento,
      precio_final = v_precio_final
  WHERE id_matricula_detalle = p_id_matricula_detalle;

  -- Si el cliente de asistencia ha cambiado, se debe regenerar el cronograma
  IF v_cliente_actual != p_id_cliente_asistencia THEN
    CALL sp_asistencia_cliente_generar_cronograma(p_id_matricula_detalle);
  END IF;
END
$$

--
-- Create procedure `sp_asistencia_cliente_eliminar_programado`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_cliente_eliminar_programado (IN p_id_asistencia_cliente int)
