REFERENCES profesores (id_profesor);

DELIMITER $$

--
-- Create procedure `sp_cursos_programados_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cursos_programados_eliminar (IN p_id int)
BEGIN
  -- Idealmente, verificar si hay matrículas asociadas antes de eliminar.
  -- Si se elimina, también se deberían limpiar las asistencias generadas.
  DELETE
    FROM asistencia_profesor
  WHERE id_curso_programado = p_id;
  DELETE
    FROM cursos_programados
  WHERE id_curso_programado = p_id;
END
$$

--
-- Create procedure `sp_asistencia_profesor_obtener_clases`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_obtener_clases (IN p_id_curso_programado int,
IN p_limit int,
IN p_offset int)
BEGIN
  SELECT
    id_asistencia_profesor,
    fecha_clase,
    estado,
    observaciones
  FROM asistencia_profesor
  WHERE id_curso_programado = p_id_curso_programado
  ORDER BY fecha_clase ASC
  LIMIT p_limit OFFSET p_offset;
END
$$

--
-- Create procedure `sp_asistencia_profesor_generar_cronograma`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_generar_cronograma (IN p_id_curso_programado int)
BEGIN
  DECLARE v_fecha_actual date;
  DECLARE v_fecha_fin date;
  DECLARE v_id_profesor int;
  DECLARE v_dias_semana varchar(20);

  -- Obtener datos de la programación
  SELECT
    fecha_inicio,
    fecha_fin,
    id_profesor,
    th.dias_semana INTO v_fecha_actual, v_fecha_fin, v_id_profesor, v_dias_semana
  FROM cursos_programados cp
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE cp.id_curso_programado = p_id_curso_programado;

  -- Limpiar cronograma existente por si se regenera
  DELETE
    FROM asistencia_profesor
  WHERE id_curso_programado = p_id_curso_programado;

  -- Bucle para generar registros de asistencia
  WHILE v_fecha_actual <= v_fecha_fin DO
    -- WEEKDAY() devuelve 0 para Lunes, 1 para Martes, etc. Se suma 1 para alinear con el formato guardado (Lunes=1, etc.)
    -- Se inserta si el día de la semana está en la cadena de días permitidos
    -- Se usa COLLATE para forzar la codificación correcta y evitar errores
    IF FIND_IN_SET(WEEKDAY(v_fecha_actual) + 1, v_dias_semana COLLATE utf8mb4_unicode_ci) THEN
        VALUES (p_id_curso_programado, v_id_profesor, v_fecha_actual, 'Programado');
    END IF;
    SET v_fecha_actual = DATE_ADD(v_fecha_actual, INTERVAL 1 DAY);
  END WHILE;
END
$$

--
-- Create procedure `sp_asistencia_profesor_eliminar_dia`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_eliminar_dia (IN p_id_asistencia_profesor int)
BEGIN
  DELETE
    FROM asistencia_profesor
  WHERE id_asistencia_profesor = p_id_asistencia_profesor
    AND estado <> 'Asisti├│';
END
$$

--
-- Create procedure `sp_asistencia_profesor_contar_clases`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_contar_clases (IN p_id_curso_programado int)
BEGIN
  SELECT
    COUNT(id_asistencia_profesor) AS total
  FROM asistencia_profesor
  WHERE id_curso_programado = p_id_curso_programado;
END
$$

--
-- Create procedure `sp_asistencia_profesor_agregar_dias`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_agregar_dias (IN p_id_curso_programado int,
IN p_fecha_fin date)
BEGIN
  DECLARE v_fecha date;
  DECLARE v_id_profesor int;
  DECLARE v_dias_semana varchar(20);
  DECLARE v_dias_agregados int DEFAULT 0;

  SELECT
    cp.fecha_inicio,
    cp.id_profesor,
    th.dias_semana INTO v_fecha, v_id_profesor, v_dias_semana
  FROM cursos_programados cp
    JOIN tipos_horario th
      ON th.id_tipo_horario = cp.id_tipo_horario
  WHERE cp.id_curso_programado = p_id_curso_programado;

  IF v_id_profesor IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Curso programado no encontrado.';
  END IF;

  IF p_fecha_fin < v_fecha THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La fecha final debe ser igual o posterior al inicio del curso.';
  END IF;

  WHILE v_fecha <= p_fecha_fin DO
    IF FIND_IN_SET(WEEKDAY(v_fecha) + 1, v_dias_semana) > 0
      AND NOT EXISTS (SELECT
          1
        FROM asistencia_profesor
        WHERE id_curso_programado = p_id_curso_programado
        AND fecha_clase = v_fecha) THEN
      SET v_dias_agregados = v_dias_agregados + 1;
    END IF;
    SET v_fecha = DATE_ADD(v_fecha, INTERVAL 1 DAY);
  END WHILE;

  SELECT
    v_dias_agregados AS dias_agregados;
END
$$

--
-- Create procedure `sp_asistencia_profesor_actualizar_estado`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_actualizar_estado (IN p_id_asistencia_profesor int,
IN p_estado enum ('Programado', 'Asistió', 'Faltó', 'Reprogramado'))
BEGIN
  UPDATE asistencia_profesor
  SET estado = p_estado
  WHERE id_asistencia_profesor = p_id_asistencia_profesor;
END
$$

--
-- Create procedure `sp_asistencia_profesor_actualizar_asistencia`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_asistencia_profesor_actualizar_asistencia (IN p_id_asistencia_profesor int,
IN p_estado enum ('Programado', 'Asistió', 'Faltó', 'Reprogramado'),
IN p_observaciones varchar(255))
BEGIN
  UPDATE asistencia_profesor
  SET estado = p_estado,
      observaciones = p_observaciones
  WHERE id_asistencia_profesor = p_id_asistencia_profesor;
END
$$

