--
-- Create table `lista_precios`
--
CREATE TABLE lista_precios (
  id_lista_precio int(11) NOT NULL AUTO_INCREMENT,
  id_curso int(11) NOT NULL,
  id_tipo_precio int(11) NOT NULL,
  precio decimal(10, 2) NOT NULL,
  vigencia_inicio date NOT NULL,
  vigencia_fin date NOT NULL,
  PRIMARY KEY (id_lista_precio)
)
ENGINE = INNODB,
AUTO_INCREMENT = 6,
AVG_ROW_LENGTH = 8192,
CHARACTER SET utf8mb4,
COLLATE utf8mb4_unicode_ci,
ROW_FORMAT = DYNAMIC;

--
-- Create index `fk_precios_curso_idx` on table `lista_precios`
--
ALTER TABLE lista_precios
ADD INDEX fk_precios_curso_idx (id_curso);

--
-- Create index `fk_precios_tipo_precio_idx` on table `lista_precios`
--
ALTER TABLE lista_precios
ADD INDEX fk_precios_tipo_precio_idx (id_tipo_precio);

--
-- Create foreign key
--
ALTER TABLE lista_precios
ADD CONSTRAINT fk_precios_curso FOREIGN KEY (id_curso)
REFERENCES cursos (id_curso);

--
-- Create foreign key
--
ALTER TABLE lista_precios
ADD CONSTRAINT fk_precios_tipo_precio FOREIGN KEY (id_tipo_precio)
REFERENCES tipos_precio (id_tipo_precio);

DELIMITER $$

--
-- Create procedure `sp_tipos_precio_verificar_dependencias`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_precio_verificar_dependencias (IN p_id_tipo_precio int)
BEGIN
  SELECT
    COUNT(id_lista_precio) AS count
  FROM lista_precios
  WHERE id_tipo_precio = p_id_tipo_precio;
END
$$

--
-- Create procedure `sp_lista_precios_obtener_por_id`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_obtener_por_id (IN p_id int)
BEGIN
  SELECT
    id_lista_precio,
    id_curso,
    id_tipo_precio,
    precio,
    vigencia_inicio,
    vigencia_fin
  FROM lista_precios
  WHERE id_lista_precio = p_id;
END
$$

--
-- Create procedure `sp_lista_precios_listar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_listar ()
BEGIN
  SELECT
    lp.id_lista_precio,
    c.nombre AS curso_nombre,
    tp.nombre AS tipo_precio_nombre,
    lp.precio,
    lp.vigencia_inicio,
    lp.vigencia_fin
  FROM lista_precios lp
    JOIN cursos c
      ON lp.id_curso = c.id_curso
    JOIN tipos_precio tp
      ON lp.id_tipo_precio = tp.id_tipo_precio
  ORDER BY c.nombre, lp.vigencia_inicio;
END
$$

--
-- Create procedure `sp_lista_precios_eliminar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_eliminar (IN p_id int)
BEGIN
  DELETE
    FROM lista_precios
  WHERE id_lista_precio = p_id;
END
$$

--
-- Create procedure `sp_lista_precios_crear`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_crear (IN p_id_curso int,
IN p_id_tipo_precio int,
IN p_precio decimal(10, 2),
IN p_vigencia_inicio date,
IN p_vigencia_fin date)
BEGIN
    VALUES (p_id_curso, p_id_tipo_precio, p_precio, p_vigencia_inicio, p_vigencia_fin);
END
$$

--
-- Create procedure `sp_lista_precios_buscar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_buscar (IN p_term varchar(100))
BEGIN
  SELECT
    lp.id_lista_precio,
    c.nombre AS curso_nombre,
    tp.nombre AS tipo_precio_nombre,
    lp.precio,
    lp.vigencia_inicio,
    lp.vigencia_fin
  FROM lista_precios lp
    JOIN cursos c
      ON lp.id_curso = c.id_curso
    JOIN tipos_precio tp
      ON lp.id_tipo_precio = tp.id_tipo_precio
  WHERE c.nombre LIKE CONCAT('%', p_term, '%')
  OR tp.nombre LIKE CONCAT('%', p_term, '%')
  ORDER BY c.nombre, lp.vigencia_inicio;
END
$$

--
-- Create procedure `sp_lista_precios_actualizar`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_lista_precios_actualizar (IN p_id_lista_precio int,
IN p_id_curso int,
IN p_id_tipo_precio int,
IN p_precio decimal(10, 2),
IN p_vigencia_inicio date,
IN p_vigencia_fin date)
BEGIN
  UPDATE lista_precios
  SET id_curso = p_id_curso,
      id_tipo_precio = p_id_tipo_precio,
      precio = p_precio,
      vigencia_inicio = p_vigencia_inicio,
      vigencia_fin = p_vigencia_fin
  WHERE id_lista_precio = p_id_lista_precio;
END
$$

--
-- Create procedure `sp_cursos_programados_buscar_disponibles`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_cursos_programados_buscar_disponibles (IN p_profesor_id int,
IN p_fecha_inicio date,
IN p_fecha_fin date)
BEGIN
  SELECT
    cp.id_curso_programado,
    c.nombre AS nombre_curso,
    c.descripcion AS curso_descripcion,
    CONCAT(p.nombres, ' ', p.apellidos) AS nombre_profesor,
    a.nombre AS area,
    sa.descripcion AS sub_area,
    sa.numero_sub_area,
    cp.fecha_inicio,
    cp.fecha_fin,
    cp.hora_inicio,
    cp.hora_fin,
    th.descripcion AS horario_dias,
    cp.vacantes_disponibles,
    (SELECT
        lp.precio
      FROM lista_precios lp
      WHERE lp.id_curso = c.id_curso
      AND cp.fecha_inicio BETWEEN lp.vigencia_inicio AND lp.vigencia_fin
      ORDER BY lp.id_tipo_precio LIMIT 1) AS precio_actual
  FROM cursos_programados cp
    JOIN cursos c
      ON cp.id_curso = c.id_curso
    JOIN profesores p
      ON cp.id_profesor = p.id_profesor
    JOIN sub_areas sa
      ON cp.id_sub_area = sa.id_sub_area
    JOIN areas a
      ON sa.id_area = a.id_area
    JOIN tipos_horario th
      ON cp.id_tipo_horario = th.id_tipo_horario
  WHERE cp.vacantes_disponibles > 0
  AND cp.estado = 'Programado'
  AND (p_profesor_id IS NULL
  OR cp.id_profesor = p_profesor_id)
  AND (p_fecha_inicio IS NULL
  OR cp.fecha_inicio >= p_fecha_inicio)
  AND (p_fecha_fin IS NULL
  OR cp.fecha_fin <= p_fecha_fin)
  ORDER BY cp.fecha_inicio;
END
$$

--
-- Create procedure `sp_tipos_horario_verificar_dependencias`
--
CREATE
DEFINER = 'root'@'localhost'
PROCEDURE sp_tipos_horario_verificar_dependencias (IN p_id_tipo_horario int)
BEGIN
  SELECT
    COUNT(id_programacion) AS count
  FROM programacion_horarios
  WHERE id_tipo_horario = p_id_tipo_horario;
END
$$

